do $$declare definition text;begin select pg_get_functiondef('club_batting_private.get_match_review_scorecard(uuid,uuid)'::regprocedure) into definition; if position('scorecard_player_links(p_club_id,snap.scorecard)' in definition)=0 then raise exception 'Unexpected scorecard function';end if;execute replace(definition,'scorecard_player_links(p_club_id,snap.scorecard)','scorecard_player_links(p_club_id,s.scorecard)');end $$;
